    }

    var result []string
    for node := head; node != nil; node = node.next {
        result = append(result, C.GoString(node.value))
    }
    C.free_list(head)
    return result, nil
}

func main() {
    var wg sync.WaitGroup
    wg.Add(2)

    go func() {
